"""Audit trail: an append-only record of every step of an agent run."""

import re
from enum import StrEnum
from typing import Self
from uuid import UUID

from pydantic import JsonValue, model_validator

from invoice_agent.domain.base import DomainModel
from invoice_agent.domain.iban import contains_iban, redact_ibans
from invoice_agent.domain.types import NonEmptyStr, UtcDatetime

# Identifiers generated by the system, never read from a document. The IBAN detector tries every
# length for a country it does not know, so about 1.5 % of random UUIDs contain a fragment that
# passes the mod 97 check: such an identifier was rewritten (audit) or refused (validator). The
# exemption is by provenance, not by shape alone: only these keys, only a value with exactly the
# shape of an identifier. Text that comes from a document never lands under these keys, and the
# detector itself stays strict (an IBAN hidden in a UUID-shaped string is still found elsewhere).
SYSTEM_ID_KEYS = frozenset(
    {
        "id",
        "run_id",
        "job_id",
        "invoice_id",
        "supplier_id",
        "purchase_order_id",
        "entry_id",
        "trace_id",
        "idempotency_key",
    }
)
_UUID = r"[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}"
_SYSTEM_ID = re.compile(rf"^(?:{_UUID}|[0-9a-f]{{32}}|post:{_UUID})$")


def is_system_identifier(key: str | None, value: str) -> bool:
    return key in SYSTEM_ID_KEYS and _SYSTEM_ID.fullmatch(value) is not None


class ActorType(StrEnum):
    SYSTEM = "system"
    AGENT = "agent"
    TOOL = "tool"
    HUMAN = "human"


class AuditEvent(DomainModel):
    id: UUID
    run_id: UUID
    step: NonEmptyStr
    actor_type: ActorType
    actor_id: NonEmptyStr
    invoice_id: UUID | None = None
    payload: dict[str, JsonValue]
    """JSON-serialisable. Decimals go in as strings; full IBANs are refused."""
    occurred_at: UtcDatetime

    @model_validator(mode="after")
    def _payload_has_no_full_iban(self) -> Self:
        if payload_contains_iban(self.payload):
            raise ValueError("payload must not contain a full IBAN, store the masked form")
        return self


def payload_contains_iban(value: JsonValue, key: str | None = None) -> bool:
    """True if a payload holds an IBAN anywhere, ignoring identifiers the system generated."""
    match value:
        case str():
            return not is_system_identifier(key, value) and contains_iban(value)
        case list():
            return any(payload_contains_iban(item, key) for item in value)
        case dict():
            return any(
                payload_contains_iban(k) or payload_contains_iban(item, k)
                for k, item in value.items()
            )
        case _:
            return False


def redact_payload(value: JsonValue, key: str | None = None) -> JsonValue:
    """Redact anything IBAN-like from every string of a payload before it is audited.

    Invoice text can end up in messages, and AuditEvent refuses full IBANs outright. The values
    of the keys in ``SYSTEM_ID_KEYS`` are kept when they look like an identifier we generated.
    """
    if isinstance(value, str):
        return value if is_system_identifier(key, value) else redact_ibans(value)
    if isinstance(value, list):
        return [redact_payload(item, key) for item in value]
    if isinstance(value, dict):
        return {k: redact_payload(item, k) for k, item in value.items()}
    return value
